package cmd

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"reflect"
	"strings"

	"github.com/spf13/cobra"
	"gopkg.in/yaml.v3"
	"k8s.io/utils/strings/slices"
)

// ValidateCmdArgs holds the arguments for the validation command.
type ValidateCmdArgs struct {
	Environments string
	Verbose      bool
	asJSON       bool
}

// ValidateResultItemType holds a result item with the correspond errors to inspect after validation.
type ValidateResultItemType struct {
	EnvironmentPath string            `json:"environment_path"`
	Status          string            `json:"status"`
	Errors          []ValidationError `json:"errors"`
}

// ValidationError holds a validation error details.
type ValidationError struct {
	Message string `json:"message"`
	Path    string `json:"path"`
}

// ValidateResultType holds ValidateResultItemType array of the validation results.
type ValidateResultType struct {
	Success bool                     `json:"success"`
	Items   []ValidateResultItemType `json:"items"`
}

const (
	statusValid   = "valid"
	statusInvalid = "invalid"
)

func (t *ValidateResultItemType) addInvalidStatus(err error, path string) {
	validateResult.Success = false
	t.Errors = append(t.Errors, ValidationError{err.Error(), path})
	t.Status = statusInvalid
}

var validateResult = ValidateResultType{
	Items:   []ValidateResultItemType{},
	Success: true,
}

var validateArgs ValidateCmdArgs

// ValidateCmd is the validation cobra command.
var ValidateCmd = setupValidateCmd()

// setupValidateCmd returns a cobra command that validates kustomize resources.
func setupValidateCmd() *cobra.Command {
	validateCmd := &cobra.Command{
		Use: "validate [path/to/repo]",
		Example: "validate" +
			"\nvalidate path/to/repo" +
			"\nvalidate my/custom/path -e default,prod" +
			"\nvalidate --verbose",
		Short:        "Validate kubernetes configuration files generated by kustomize",
		RunE:         getKustomizeValidateCmd(),
		SilenceUsage: true,
	}

	validateCmd.Flags().StringVarP(
		&validateArgs.Environments,
		"environments",
		"e",
		"",
		"Comma separated list of environments to validate",
	)

	validateCmd.Flags().BoolVarP(
		&validateArgs.asJSON,
		"json",
		"j",
		false,
		"Output as JSON",
	)

	validateCmd.Flags().BoolVar(
		&validateArgs.Verbose,
		"verbose",
		false,
		"When set to true, prints verbose validation error messages",
	)

	RootCmd.AddCommand(validateCmd)

	validateArgs = ValidateCmdArgs{}
	validateResult = ValidateResultType{
		Items:   []ValidateResultItemType{},
		Success: true,
	}

	return validateCmd
}

// getKustomizeValidateCmd returns a cobra command that validates kustomize resources.
func getKustomizeValidateCmd() func(cmd *cobra.Command, args []string) error {
	return func(cmd *cobra.Command, args []string) error {
		outputPath, kustConfigPath, err := getAbsPaths(args, "")
		if err != nil {
			return err
		}

		if _, err := os.Stat(outputPath); os.IsNotExist(err) {
			return fmt.Errorf("output path '%s' does not exist", outputPath)
		}

		if _, err := os.Stat(kustConfigPath); os.IsNotExist(err) {
			return fmt.Errorf("kustomization config path '%s' does not exist", kustConfigPath)
		}

		if err := validateConfigPath(kustConfigPath); err != nil {
			return err
		}

		if err := ValidateOverlays(cmd, outputPath, kustConfigPath+"/"+overlaysDir); err != nil {
			return err
		}

		return getResults(cmd, validateResult)
	}
}

// getResults prints the results of the validation.
func getResults(cmd *cobra.Command, result ValidateResultType) error {
	if validateArgs.asJSON {
		return printJSON(cmd, result)
	}

	return printText(cmd, result)
}

// printText prints textual results of the validation (default).
func printText(cmd *cobra.Command, result ValidateResultType) error {
	if result.Success {
		cmd.Print("Validated successfully\n")
		return nil
	}

	isError := false
	for _, item := range result.Items {
		if item.Status == statusValid {
			continue
		}
		isError = true

		printf(cmd, "Failed to validate '%s'", item.EnvironmentPath)

		for _, err := range item.Errors {
			printf(cmd, " %s\n path: %s", err.Message, err.Path)
		}
	}
	if isError {
		return errors.New("validation failed")
	}

	return nil
}

// printJSON prints the results of the validation as JSON.
func printJSON(cmd *cobra.Command, result ValidateResultType) error {
	b, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return err
	}

	cmd.Print(string(b))

	return nil
}

// ValidateOverlays validates the overlays directory.
func ValidateOverlays(cmd *cobra.Command, outputPath, overlaysPath string) error {
	kustomizeBuildCmd, outputFile, err := newKustomizeBuildCmd()
	if err != nil {
		return err
	}

	var overlays []os.DirEntry
	if overlays, err = getOverlays(overlaysPath); err != nil {
		resItem := ValidateResultItemType{
			EnvironmentPath: overlaysPath,
			Status:          statusValid,
			Errors:          []ValidationError{},
		}
		resItem.addInvalidStatus(err, overlaysPath)

		validateResult = appendResultItem(validateResult, resItem)
		return nil
	}

	envs := getEnvs(validateArgs.Environments)
	if err := validateEnvs(overlays, envs); err != nil {
		return err
	}

	for _, overlay := range overlays {
		if len(envs) > 0 && !slices.Contains(envs, overlay.Name()) {
			continue
		}

		overlayPath := outputPath + "/" + overlay.Name()

		resItem := ValidateResultItemType{
			EnvironmentPath: overlayPath,
			Status:          statusValid,
			Errors:          []ValidationError{},
		}

		printf(cmd, "Validating environment '%s'... ", overlay.Name())

		overlayBasePath := overlaysPath + "/" + overlay.Name()
		if err = kustomizeBuildCmd.RunE(kustomizeBuildCmd, []string{overlayBasePath}); err != nil {
			resItem.addInvalidStatus(fmt.Errorf("failed to build the env internally '%s': %w", overlay.Name(), err), overlayBasePath)
		}

		var decoder *yaml.Decoder
		if decoder, err = getYAMLDecoder(outputFile.Name()); err != nil {
			resItem.addInvalidStatus(err, overlayBasePath)
		}

		if path, err := ValidateYAMLs(decoder, overlayPath); err != nil {
			resItem.addInvalidStatus(err, path)
		}

		if err := resetFile(outputFile); err != nil {
			resItem.addInvalidStatus(fmt.Errorf("failed to reset output file '%s': %w", outputFile.Name(), err), overlayBasePath)
		}

		if resItem.Status == statusValid {
			printf(cmd, "✓ Valid\n")
		} else {
			printf(cmd, "✗ Invalid\n")
		}
		validateResult = appendResultItem(validateResult, resItem)
	}

	return nil
}

// appendResultItem appends a result item to the result buffer.
func appendResultItem(result ValidateResultType, item ValidateResultItemType) ValidateResultType {
	result.Items = append(result.Items, item)
	return result
}

// ValidateYAMLs iterates over the YAML documents and validates them.
func ValidateYAMLs(expectedYamlDecoder *yaml.Decoder, outputDir string) (string, error) {
	expectedNumberOfResources := 0
	for {
		var expectedYaml map[string]interface{}
		err := expectedYamlDecoder.Decode(&expectedYaml)
		if errors.Is(err, io.EOF) {
			break
		}
		expectedNumberOfResources++

		if err != nil {
			return outputDir, fmt.Errorf("error decoding YAML: %w", err)
		}

		// we have to ensure fields exist because these fields are used to resolve the path of the manifest we're about to validate.
		if err = ensureFields(expectedYaml); err != nil {
			return outputDir, fmt.Errorf("missing fields found in YAML: %w", err)
		}

		parentDir, filePath, _, err := getPaths(expectedYaml, outputDir)
		if err != nil {
			return filePath, fmt.Errorf("error getting paths: %w", err)
		}

		if _, err := os.Stat(parentDir); os.IsNotExist(err) {
			return parentDir, fmt.Errorf("directory '%s' does not exist", parentDir)
		}

		actualYamlDecoder, err := getYAMLDecoder(filePath)
		if err != nil {
			return filePath, err
		}

		var actualYaml map[string]interface{}
		err = actualYamlDecoder.Decode(&actualYaml)
		if err != nil {
			return filePath, fmt.Errorf("error decoding file '%s': %w", filePath, err)
		}

		if !reflect.DeepEqual(actualYaml, expectedYaml) {
			errMsg := fmt.Sprintf("file '%s' does not match generated file", filePath)
			if validateArgs.Verbose {
				expectedBytes, err := yaml.Marshal(expectedYaml)
				if err != nil {
					return filePath, fmt.Errorf("error marshaling YAML: %w", err)
				}
				value := string(expectedBytes)
				errMsg = fmt.Sprintf("file '%s' does not match generated file:\n"+value, filePath)
			}

			return filePath, errors.New(errMsg)
		}
	}
	actualNumberOfResources, err := getNumberOfResources(outputDir)
	if err != nil {
		return outputDir, fmt.Errorf("error getting number of resources: %w", err)
	}
	if expectedNumberOfResources != actualNumberOfResources {
		return outputDir, fmt.Errorf("expected %d resources, got %d", expectedNumberOfResources, actualNumberOfResources)
	}
	return "", nil
}

// As output dir is generated by kustomize, where resources are saved into seprarate files,
// it is enough to count number of files in the output dir to get number of resources.
func getNumberOfResources(outputDir string) (int, error) {
	var actualNumberOfResources int
	err := filepath.WalkDir(outputDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() {
			if strings.HasSuffix(d.Name(), ".yml") || strings.HasSuffix(d.Name(), ".yaml") {
				actualNumberOfResources++
			}
		}
		return nil
	})
	return actualNumberOfResources, err
}

// printf wrapper around Sprintf, to print a string to the console if the JSON flag was not specified.
func printf(cmd *cobra.Command, format string, i ...interface{}) {
	if validateArgs.asJSON {
		return
	}

	cmd.Print(fmt.Sprintf(format, i...))
}
